use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,instance::factor_base};
const Q:u64=601;const N:u64=411491;
fn mul(a:u64,b:u64)->u64{a*b%Q}fn add(a:u64,b:u64)->u64{(a+b)%Q}
fn mons()->Vec<[usize;4]>{let mut v=vec![];for a in 0..=5{for b in 0..=5-a{for c in 0..=5-a-b{v.push([a,b,c,5-a-b-c]);}}}v}
fn map(rows:&[Vec<u64>],ms:&[[usize;4]],k:[u64;4])->[u64;4]{let mut powers=[[1u64;6];4];for j in 0..4{for n in 1..6{powers[j][n]=mul(powers[j][n-1],k[j]);}}let vs:Vec<_>=ms.iter().map(|e|(0..4).fold(1,|s,j|mul(s,powers[j][e[j]]))).collect();std::array::from_fn(|i|rows[i].iter().zip(&vs).fold(0,|s,(&a,&b)|add(s,mul(a,b))))}
fn same(a:[u64;4],b:[u64;4])->bool{let Some(j)=a.iter().position(|&x|x!=0)else{return false};b[j]!=0&&(0..4).all(|i|mul(a[i],b[j])==mul(b[i],a[j]))}
fn project(c:&Curve,d:&Div)->[u64;4]{let f=&c.fp;match d.u.deg(){0=>[0,0,0,1],1=>{let x=f.neg(d.u.c[0]);[0,1,x,f.mul(c.f.c[5],f.mul(x,x))]},2=>{let s=f.neg(d.u.c[1]);let p=d.u.c[0];let s2=f.mul(s,s);let corr=f.add(c.f.c[2],f.add(f.mul(c.f.c[3],s),f.add(f.mul(c.f.c[4],s2),f.mul(c.f.c[5],f.mul(s,f.sub(s2,p))))));[1,s,p,f.sub(f.mul(d.v.c[1],d.v.c[1]),corr)]},_=>panic!()}}
fn lift(c:&Curve,k:[u64;4])->Div{let f=&c.fp;if k[0]==0{if k[1]==0{assert_eq!(k[2],0);assert_ne!(k[3],0);return c.zero()}let x=f.mul(k[2],f.inv(k[1]));let y=f.sqrt(c.f.eval(x,f)).unwrap();let d=c.place(x,y);assert!(same(k,project(c,&d)));return d}
 let iv=f.inv(k[0]);let s=f.mul(k[1],iv);let p=f.mul(k[2],iv);let h=f.mul(k[3],iv);let s2=f.mul(s,s);let t=f.add(h,f.add(c.f.c[2],f.add(f.mul(c.f.c[3],s),f.add(f.mul(c.f.c[4],s2),f.mul(c.f.c[5],f.mul(s,f.sub(s2,p)))))));let b1=f.sqrt(t).unwrap();let u=Poly::from_coeffs(&[p,f.neg(s),1]);let rem=c.f.rem(&u,f);let b0=if b1!=0{f.mul(f.sub(rem.c[1],f.mul(s,t)),f.inv(f.add(b1,b1)))}else{assert_eq!(rem.c[1],0);f.sqrt(rem.c[0]).unwrap()};let d=Div{u,v:Poly::from_coeffs(&[b0,b1])};assert!(c.is_valid(&d));assert!(same(k,project(c,&d)));d}
fn main(){counted::disable();assert!((2..).take_while(|&i|i*i<=N).all(|i|N%i!=0));let source=Curve::new(Fp::new(Q),Poly::from_coeffs(&[7,0,0,0,0,1]));let target=Curve::new(Fp::new(Q),Poly::from_coeffs(&[209,127,378,47,539,495]));let rows:Vec<Vec<u64>>=include_str!("../coordinate-identity/CONTROL.txt").lines().filter(|l|l.starts_with("STANDARD_MAP\t")).map(|l|l.split('\t').nth(2).unwrap().split(',').map(|s|s.parse().unwrap()).collect()).collect();assert_eq!(rows.len(),4);let ms=mons();assert_eq!(ms.len(),56);for r in &rows{assert_eq!(r.len(),56)}let fb=factor_base(&source);let d=source.place(fb[0].0,fb[0].1);assert!(!source.is_zero(&d));assert!(source.is_zero(&source.mul(&d,N)));let image=lift(&target,map(&rows,&ms,project(&source,&d)));assert!(!target.is_zero(&image));assert!(target.is_zero(&target.mul(&image,N)));println!("SOURCE_D\tu={:?}\tv={:?}",&d.u.c[..d.u.n],&d.v.c[..d.v.n]);println!("IMAGE_D\tu={:?}\tv={:?}",&image.u.c[..image.u.n],&image.v.c[..image.v.n]);
 let(mut p,mut q)=(source.zero(),target.zero());let mut degrees=[0u64;3];let mut target_degrees=[0u64;3];let mut repeats=0;let mut lifts=0;for k in 0..N{if k>0{assert!(!source.is_zero(&p));assert!(!target.is_zero(&q));}assert!(source.is_valid(&p));assert!(target.is_valid(&q));let a=map(&rows,&ms,project(&source,&p));assert!(a.iter().any(|&x|x!=0));assert!(same(a,project(&target,&q)),"scalarposition={k}");let z=lift(&target,a);assert!(z==q||z==target.neg(&q));lifts+=1;degrees[p.u.deg()as usize]+=1;target_degrees[q.u.deg()as usize]+=1;if p.u.deg()==2&&Poly::gcd(&p.u,&p.u.deriv(&source.fp),&source.fp).deg()>0{repeats+=1;}p=source.add(&p,&d);q=target.add(&q,&image);if k%65536==0{eprintln!("checked_scalar_positions={}",k+1);}}
 assert!(source.is_zero(&p));assert!(target.is_zero(&q));assert_eq!(degrees.iter().sum::<u64>(),N);println!("scalar_positions={N} nonzero_map_checks={N} canonical_lift_checks={lifts} source_degrees={degrees:?} target_degrees={target_degrees:?} repeated_support_positions={repeats} full_rational_cyclic_Kummer_compatibility=true independent_verification=false");}
